<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Bouncing Balls</title>
<style>
  :root {
    --bg: #0b0d12;
    --panel: #141821;
    --ink: #e8edf7;
    --muted: #8b95a8;
    --accent: #5ee0a0;
    --accent-2: #6aa8ff;
    --danger: #ff6b7a;
  }
  * { box-sizing: border-box; margin: 0; padding: 0; }
  html, body {
    height: 100%;
    background: radial-gradient(1200px 700px at 50% -10%, #1a2233 0%, var(--bg) 55%);
    color: var(--ink);
    font-family: ui-sans-serif, system-ui, -apple-system, Segoe UI, sans-serif;
  }
  body {
    display: flex;
    align-items: center;
    justify-content: center;
    min-height: 100%;
    padding: 24px;
  }
  .app {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 16px;
  }
  h1 {
    font-size: 20px;
    font-weight: 650;
    letter-spacing: 0.04em;
    text-transform: uppercase;
    color: var(--muted);
  }
  canvas#sim {
    width: 600px;
    height: 600px;
    background:
      radial-gradient(circle at 50% 30%, rgba(106,168,255,0.08), transparent 55%),
      #0e121a;
    border-radius: 16px;
    box-shadow:
      0 0 0 1px rgba(255,255,255,0.06),
      0 24px 60px rgba(0,0,0,0.45);
    cursor: crosshair;
    display: block;
  }
  .controls {
    display: flex;
    gap: 10px;
  }
  button {
    appearance: none;
    border: 0;
    border-radius: 999px;
    padding: 10px 18px;
    font-size: 14px;
    font-weight: 600;
    letter-spacing: 0.02em;
    color: #0b0d12;
    background: var(--accent);
    cursor: pointer;
    transition: transform 0.08s ease, filter 0.15s ease, background 0.15s ease;
  }
  button:hover { filter: brightness(1.08); }
  button:active { transform: translateY(1px) scale(0.98); }
  #play { background: var(--accent-2); }
  #clear { background: var(--danger); color: #1a0a0c; }
  button.paused { background: #c9d4e8; }
</style>
</head>
<body>
  <div class="app">
    <h1>Physics Playground</h1>
    <canvas id="sim" width="600" height="600"></canvas>
    <div class="controls">
      <button id="drop" type="button">Drop</button>
      <button id="play" type="button">Pause</button>
      <button id="clear" type="button">Clear</button>
    </div>
  </div>
<script>
(function () {
  const canvas = document.getElementById('sim');
  const ctx = canvas.getContext('2d');
  const W = canvas.width;
  const H = canvas.height;
  const GRAVITY = 0.45;
  const REST = 0.82;
  const DEFAULT_R = 18;
  const PALETTE = ['#5ee0a0', '#6aa8ff', '#ffd166', '#ff6b7a', '#c084fc', '#67e8f9'];

  const balls = [];
  let playing = true;
  let raf = 0;

  function clampBall(b) {
    if (b.r < 2) b.r = 2;
    const maxR = Math.min(W, H) / 2 - 0.5;
    if (b.r > maxR) b.r = maxR;
    if (b.x < b.r) b.x = b.r;
    if (b.x > W - b.r) b.x = W - b.r;
    if (b.y < b.r) b.y = b.r;
    if (b.y > H - b.r) b.y = H - b.r;
  }

  function addBall(x, y, vx, vy, r) {
    const ball = {
      x: Number(x),
      y: Number(y),
      vx: vx == null ? 0 : Number(vx),
      vy: vy == null ? 0 : Number(vy),
      r: r == null ? DEFAULT_R : Number(r),
      color: PALETTE[(Math.random() * PALETTE.length) | 0]
    };
    if (!isFinite(ball.x)) ball.x = W / 2;
    if (!isFinite(ball.y)) ball.y = ball.r;
    if (!isFinite(ball.vx)) ball.vx = 0;
    if (!isFinite(ball.vy)) ball.vy = 0;
    if (!isFinite(ball.r) || ball.r <= 0) ball.r = DEFAULT_R;
    clampBall(ball);
    balls.push(ball);
    draw();
    return ball;
  }

  function clearBalls() {
    balls.length = 0;
    draw();
  }

  function collide(b) {
    if (b.x - b.r < 0) {
      b.x = b.r;
      b.vx = Math.abs(b.vx) * REST;
    } else if (b.x + b.r > W) {
      b.x = W - b.r;
      b.vx = -Math.abs(b.vx) * REST;
    }
    if (b.y - b.r < 0) {
      b.y = b.r;
      b.vy = Math.abs(b.vy) * REST;
    } else if (b.y + b.r > H) {
      b.y = H - b.r;
      b.vy = -Math.abs(b.vy) * REST;
    }
  }

  function step(dt) {
    if (dt == null) dt = 1;
    dt = Number(dt);
    if (!isFinite(dt)) dt = 1;
    for (let i = 0; i < balls.length; i++) {
      const b = balls[i];
      b.vy += GRAVITY * dt;
      b.x += b.vx * dt;
      b.y += b.vy * dt;
      collide(b);
      clampBall(b);
    }
    draw();
  }

  function draw() {
    ctx.clearRect(0, 0, W, H);
    ctx.save();
    ctx.strokeStyle = 'rgba(255,255,255,0.04)';
    ctx.lineWidth = 1;
    for (let g = 40; g < W; g += 40) {
      ctx.beginPath();
      ctx.moveTo(g + 0.5, 0);
      ctx.lineTo(g + 0.5, H);
      ctx.stroke();
    }
    for (let g = 40; g < H; g += 40) {
      ctx.beginPath();
      ctx.moveTo(0, g + 0.5);
      ctx.lineTo(W, g + 0.5);
      ctx.stroke();
    }
    ctx.restore();

    for (let i = 0; i < balls.length; i++) {
      const b = balls[i];
      const grd = ctx.createRadialGradient(
        b.x - b.r * 0.35, b.y - b.r * 0.4, b.r * 0.1,
        b.x, b.y, b.r
      );
      grd.addColorStop(0, '#ffffff');
      grd.addColorStop(0.18, b.color);
      grd.addColorStop(1, shade(b.color, 0.45));
      ctx.beginPath();
      ctx.fillStyle = grd;
      ctx.arc(b.x, b.y, b.r, 0, Math.PI * 2);
      ctx.fill();
      ctx.strokeStyle = 'rgba(0,0,0,0.25)';
      ctx.lineWidth = 1.5;
      ctx.stroke();
    }
  }

  function shade(hex, t) {
    const n = parseInt(hex.slice(1), 16);
    const r = (n >> 16) & 255, g = (n >> 8) & 255, b = n & 255;
    return 'rgb(' + ((r * t) | 0) + ',' + ((g * t) | 0) + ',' + ((b * t) | 0) + ')';
  }

  function canvasPoint(ev) {
    const rect = canvas.getBoundingClientRect();
    const sx = canvas.width / rect.width;
    const sy = canvas.height / rect.height;
    return {
      x: (ev.clientX - rect.left) * sx,
      y: (ev.clientY - rect.top) * sy
    };
  }

  function dropBall() {
    const r = 12 + Math.random() * 16;
    const x = r + Math.random() * (W - 2 * r);
    const y = r + 8 + Math.random() * 40;
    const vx = (Math.random() - 0.5) * 8;
    addBall(x, y, vx, 0, r);
  }

  function loop() {
    if (!playing) return;
    step(1);
    raf = requestAnimationFrame(loop);
  }

  function setPlaying(on) {
    playing = !!on;
    const btn = document.getElementById('play');
    btn.textContent = playing ? 'Pause' : 'Play';
    btn.classList.toggle('paused', !playing);
    if (playing) {
      cancelAnimationFrame(raf);
      raf = requestAnimationFrame(loop);
    } else {
      cancelAnimationFrame(raf);
    }
  }

  canvas.addEventListener('pointerdown', function (ev) {
    const p = canvasPoint(ev);
    const r = 12 + Math.random() * 14;
    addBall(p.x, p.y, (Math.random() - 0.5) * 6, (Math.random() - 0.5) * 4, r);
  });

  document.getElementById('drop').addEventListener('click', dropBall);
  document.getElementById('play').addEventListener('click', function () {
    setPlaying(!playing);
  });
  document.getElementById('clear').addEventListener('click', clearBalls);

  window.sim = {
    w: W,
    h: H,
    balls: function () {
      return balls.map(function (b) {
        return { x: b.x, y: b.y, vx: b.vx, vy: b.vy, r: b.r };
      });
    },
    addBall: function (x, y, vx, vy, r) {
      addBall(x, y, vx == null ? 0 : vx, vy == null ? 0 : vy, r);
    },
    clear: clearBalls,
    step: step
  };

  draw();
  setPlaying(true);
})();
</script>
</body>
</html>
